<?php

declare(strict_types=1);

namespace Shirakaba\Tools\Docs;

/**
 * Builds packages/docs/api.md: every public class, interface, enum and trait of every
 * package with the first sentence of its documentation and its path once installed
 *. Classes marked @internal or in an Internal namespace are left out.
 */
final readonly class ApiIndex
{
    public static function generate(string $packages): string
    {
        $lines = [
            '# API index',
            '',
            'Generated by `composer docs:generate`; do not edit. Every public type of every Shirakaba package,',
            'with the first sentence of its documentation. Paths are relative to `vendor/shirakaba/`.',
        ];
        $directories = glob($packages . '/*', GLOB_ONLYDIR);
        $directories = $directories === false ? [] : $directories;
        sort($directories);
        foreach ($directories as $directory) {
            $package = basename($directory);
            $types = self::types($directory . '/src', $package);
            if ($types === []) {
                continue;
            }
            $lines[] = '';
            $lines[] = '## shirakaba/' . $package;
            $lines[] = '';
            foreach ($types as [$name, $kind, $summary, $path]) {
                $lines[] = sprintf('- `%s` (%s, `%s`)%s', $name, $kind, $path, $summary === '' ? '' : ': ' . $summary);
            }
        }

        return implode("\n", $lines) . "\n";
    }

    /**
     * @return list<array{string, string, string, string}> name, kind, summary, installed path
     */
    private static function types(string $source, string $package): array
    {
        if (!is_dir($source)) {
            return [];
        }
        $types = [];
        $files = new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($source, \FilesystemIterator::SKIP_DOTS));
        foreach ($files as $file) {
            if (!$file instanceof \SplFileInfo || $file->getExtension() !== 'php') {
                continue;
            }
            $relative = substr($file->getPathname(), strlen($source) + 1);
            if (str_starts_with($relative, 'Internal/') || str_contains($relative, '/Internal/')) {
                continue;
            }
            $code = (string) file_get_contents($file->getPathname());
            if (preg_match('/^namespace ([^;]+);/m', $code, $namespace) !== 1) {
                continue;
            }
            if (preg_match('/(\/\*\*(?:(?!\*\/).)*\*\/)\s*(?:#\[[^\n]*\]\s*)*(?:final\s+|abstract\s+|readonly\s+)*(class|interface|enum|trait)\s+(\w+)/s', $code, $match) !== 1
                && preg_match('/^(?:final\s+|abstract\s+|readonly\s+)*(class|interface|enum|trait)\s+(\w+)/m', $code, $bare) !== 1) {
                continue;
            }
            $doc = $match[1] ?? '';
            $kind = $match[2] ?? ($bare[1] ?? 'class');
            $name = $match[3] ?? ($bare[2] ?? '');
            if ($name === '' || str_contains($doc, '@internal')) {
                continue;
            }
            $types[] = [$namespace[1] . '\\' . $name, $kind, self::summary($doc), $package . '/src/' . $relative];
        }
        usort($types, static fn (array $a, array $b): int => strcmp($a[0], $b[0]));

        return $types;
    }

    private static function summary(string $doc): string
    {
        $text = '';
        foreach (explode("\n", $doc) as $line) {
            $line = trim(preg_replace('/^\s*(\/\*\*|\*\/|\*)\s?/', '', $line) ?? '');
            if ($line === '' && $text !== '') {
                break;
            }
            if ($line === '' || str_starts_with($line, '@')) {
                continue;
            }
            $text .= ($text === '' ? '' : ' ') . $line;
        }
        $sentence = preg_match('/^(.+?[.!?])(\s|$)/', $text, $match) === 1 ? $match[1] : $text;

        return trim($sentence);
    }
}
